from taf.rfrl.utilities.tl_config import load_moler_configuration_from_tl


@load_moler_configuration_from_tl()
def start_tcpdump_on_device(device, interface, capture_file, count=0, duration=0, background=False,
                            timeout=300, additional_options=None, execute_by_sudo=False):
    """
    Start tcpdump collection on the selected interface of the selected device
    :param device           Device object where to start tcpdump collection
    :param interface:       Interface of the selected device
    :param capture_file:    Name of the capture file
    :param count:           Number of packets to be captured
    :param duration:        Duration of tcpdump in seconds
    :param background:      Flag if tcpdump should run in the background
    :param timeout:         Timeout in seconds to be set for the tcpdump command
    :param additional_options: options be added to tcpdump command
    :param execute_by_sudo:    Flag if tcpdump collection should be executed with sudo privileges
    """
    options = "-i {} -w {}".format(interface, capture_file)
    if duration:
        options = options + ' -Z root -G {} -W 1'.format(duration)
        if timeout < duration:
            timeout = duration
    elif count:
        options = options + ' -c {}'.format(count)

    if additional_options:
        options = options + ' {}'.format(additional_options)

    if background:
        options = options + '&'

    tcpdump_cmd = device.get_cmd(cmd_name='tcpdump',
                                 cmd_params={
                                     'options': options
                                 })
    if execute_by_sudo:
        sudo_cmd = device.get_cmd(cmd_name='sudo',
                                  cmd_params={
                                      'cmd_object': tcpdump_cmd
                                  })
        sudo_cmd(timeout=timeout)
    else:
        tcpdump_cmd(timeout=timeout)


@load_moler_configuration_from_tl()
def stop_tcpdump_on_device(device, kill_by_sudo=False):
    """
    Optional keyword for stopping the tcpdump collection on the BTS device
    :param device           Device object where to stop tcpdump collection
    :param kill_by_sudo:    Flag if tcpdump collection should be stopped with sudo privileges
    """
    ps_cmd = device.get_cmd(cmd_name='ps',
                            cmd_params={
                                'options': '-ef'
                            })
    processes_to_kill = " ".join([str(process['PID']) for process in ps_cmd() if 'tcpdump' in process['CMD']])
    kill_cmd = device.get_cmd(cmd_name='kill',
                              cmd_params={'options': '-9', 'pid': processes_to_kill})
    if kill_by_sudo:
        sudo_kill = device.get_cmd(cmd_name='sudo',
                                   cmd_params={
                                       'cmd_object': kill_cmd
                                   })
        sudo_kill()
    else:
        kill_cmd()
